def transform(grid):
    h, w = len(grid), len(grid[0])
    for r in range(h):
        if len(set(grid[r])) == 1 and 0 < r < h - 1 and r == h-r-1:
            a, b = grid[:r], grid[r+1:]
            shared = set(v for row in a for v in row) & set(v for row in b for v in row)
            shared.discard(grid[r][0])
            if len(shared) == 1:
                color = next(iter(shared))
                # Sparse isolated color on the first side denotes a uniform fill.
                if sum(v == color for row in a for v in row) == 1:
                    return [[color] * w for _ in range(r)]
                # Otherwise compare both panels; mark equal cells with 3.
                return [[3 if a[y][x] == b[y][x] else color for x in range(w)] for y in range(r)]
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid) and 0 < c < w-1 and c == w-c-1:
            a = [row[:c] for row in grid]
            b = [row[c+1:] for row in grid]
            shared = set(v for row in a for v in row) & set(v for row in b for v in row)
            shared.discard(grid[0][c])
            if len(shared) == 1:
                color = next(iter(shared))
                if sum(v == color for row in a for v in row) == 1:
                    return [[color] * c for _ in range(h)]
                return [[3 if a[y][x] == b[y][x] else color for x in range(c)] for y in range(h)]
    return grid
